SELECT I.InvoiceID, I.InvoiceNo, I.CustomerID, C.CustomerName, I.CustomerPOID, PO.PONumber, I.SalesOrderID, SO.SalesOrderNo, I.InvoiceDate, I.InvoiceType, I.PaymentTerms, I.BillToName, I.BillToAddress, I.SubtotalAmount, I.TaxAmount, I.GrandTotalAmount, I.InvoiceStatus, I.Notes, "Value Transformation LLC" AS CompanyName, "1211 Heath Church Road" AS CompanyAddress1, "Lexington, NC, 27292, phone: 336-963-0119" AS CompanyAddress2, "email: Jon.Quigley@ValueTransform.com" AS CompanyEmail, "Product Development Experts - Training and Consulting" AS CompanyFooter, Nz(I.Notes,"") AS InvoiceDescription
FROM ((T_Invoices AS I LEFT JOIN T_Customers AS C ON I.CustomerID = C.CustomerID) LEFT JOIN T_CustomerPOs AS PO ON I.CustomerPOID = PO.CustomerPOID) LEFT JOIN T_SalesOrders AS SO ON I.SalesOrderID = SO.SalesOrderID;

